CREATE     PROCEDURE [synapse_fo].[usp_Insert_BUDGETRESERVATIONLINE_PSN]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:39
	Description: Insert stored procedure for BUDGETRESERVATIONLINE_PSN from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[BUDGETRESERVATIONLINE_PSN]
	(
		[ACCOUNTINGDISTRIBUTIONTEMPLATE],
		[ACTIVITYNUMBER],
		[BUDGETRESERVATIONHEADER_PSN],
		[CREATEDDATETIME],
		[CURRENCY],
		[DATAAREAID],
		[DataLakeModified_DateTime],
		[FileName],
		[LastProcessedChange_DateTime],
		[LEDGERDIMENSION],
		[LINEAMOUNT],
		[LINENUMBER],
		[LSN],
		[PARTITION],
		[PROCUREMENTCATEGORY],
		[PROJCATEGORYID],
		[PROJID],
		[PROJLINEPROPERTYID],
		[PROJSALESCURRENCYID],
		[PROJSALESPRICE],
		[PROJSALESUNITID],
		[PROJTAXGROUPID],
		[PROJTAXITEMGROUPID],
		[PROJTRANSID],
		[PROJWORKER],
		[PURCHREQLINE],
		[QUANTITY],
		[RECID],
		[RECVERSION],
		[SOURCEDOCUMENTLINE],
		[SysRowId],
		[TRANSACTIONTEXT],
		[UNITPRICE]
	)
	SELECT 
		stg.[ACCOUNTINGDISTRIBUTIONTEMPLATE],
		stg.[ACTIVITYNUMBER],
		stg.[BUDGETRESERVATIONHEADER_PSN],
		stg.[CREATEDDATETIME],
		stg.[CURRENCY],
		stg.[DATAAREAID],
		stg.[DataLakeModified_DateTime],
		stg.[FileName],
		stg.[LastProcessedChange_DateTime],
		stg.[LEDGERDIMENSION],
		stg.[LINEAMOUNT],
		stg.[LINENUMBER],
		stg.[LSN],
		stg.[PARTITION],
		stg.[PROCUREMENTCATEGORY],
		stg.[PROJCATEGORYID],
		stg.[PROJID],
		stg.[PROJLINEPROPERTYID],
		stg.[PROJSALESCURRENCYID],
		stg.[PROJSALESPRICE],
		stg.[PROJSALESUNITID],
		stg.[PROJTAXGROUPID],
		stg.[PROJTAXITEMGROUPID],
		stg.[PROJTRANSID],
		stg.[PROJWORKER],
		stg.[PURCHREQLINE],
		stg.[QUANTITY],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[SOURCEDOCUMENTLINE],
		stg.[SysRowId],
		stg.[TRANSACTIONTEXT],
		stg.[UNITPRICE]	
	FROM [staging_fo].[BUDGETRESERVATIONLINE_PSN] stg
		LEFT JOIN [synapse_fo].[BUDGETRESERVATIONLINE_PSN] tgt
			ON stg.[RECID] = tgt.[RECID] 
		
	WHERE tgt.[RECID] IS NULL
END
